situation_breach_shroud = {
	title = situation_breach_shroud
	desc = situation_breach_shroud_desc
	picture = {
		trigger = {
			owner = { is_hive_empire = yes }
		}
		picture = GFX_evt_shroud_psionic_hive_mind
	}
	picture = {
		trigger = {
			owner = {
				founder_species = { is_archetype = MACHINE }
			}
		}
		picture = GFX_evt_machine_sapience
	}
	picture = {
		trigger = {
			owner = {
				is_hive_empire = no
				founder_species = { NOT = { is_archetype = MACHINE } }
			}
		}
		picture = GFX_evt_psionics
	}
	category = neutral
	complete_icon_frame = GFX_situation_outcome_frame_green
	complete_icon = GFX_situation_outcome_ascension
	initial_progress = @breach_shroud_start_value
	situation_log_category = urgent_matters

	on_start = {
		owner = {
			set_country_flag = can_access_shroud
			roll_ai_preferred_patron = yes
		}
	}
	on_progress_complete = {
		custom_tooltip = situation_breach_shroud_finish_effects
		hidden_effect = {
			situation_event = { id = shroud.2800 }
		}
		set_situation_locked = yes
	}

	stages = {
		stage_1 = {
			icon = GFX_situation_stage_1
			icon_background = GFX_situation_stage_frame_green
			end = @breach_shroud_stage_1_end
			custom_tooltip = situation_breach_shroud_effects
			on_first_enter = {
				set_situation_flag = breach_shroud_stage_1_started
			}
		}
		stage_2 = {
			icon = GFX_situation_stage_2
			icon_background = GFX_situation_stage_frame_green
			end = @breach_shroud_stage_2_end
			custom_tooltip = situation_breach_shroud_effects
			on_first_enter = {
				set_situation_flag = breach_shroud_stage_2_started
				remove_situation_flag = breach_shroud_approach_selected
				situation_event = {
					id = shroud.2760
				}
			}
		}
		stage_3 = {
			icon = GFX_situation_stage_3
			icon_background = GFX_situation_stage_frame_green
			end = @breach_shroud_end_value
			custom_tooltip = situation_breach_shroud_effects
			on_first_enter = {
				set_situation_flag = breach_shroud_stage_3_started
				remove_situation_flag = breach_shroud_approach_selected
				situation_event = {
					id = shroud.2780
				}
			}
		}
	}

	approach = {
		name = approach_situation_breach_shroud_nothing
		icon = GFX_situation_approach_shrug
		icon_background = GFX_situation_approach_bg_yellow
		default = yes
		on_select = {
			custom_tooltip = breach_shroud_nothing_tooltip
		}
	}
	approach = {
		name = approach_situation_breach_shroud_meditate
		icon = GFX_situation_approach_unity
		icon_background = GFX_situation_approach_bg_green
		on_select = {
			set_situation_flag = beneficial_approach
			custom_tooltip = approach_situation_beneficial_tooltip
			custom_tooltip = breach_shroud_meditate_tooltip
		}
		modifier = {
			country_unity_produces_mult = -0.25
		}
		ai_weight = {
			base = 0
			modifier = {
				add = 1
				owner = { has_ethic = ethic_spiritualist }
			}
			modifier = {
				add = 2
				owner = { has_ethic = ethic_fanatic_spiritualist }
			}
		}
	}
	approach = {
		name = approach_situation_breach_shroud_commune_resources
		icon = GFX_situation_approach_zro
		icon_background = GFX_situation_approach_bg_yellow
		potential = {
			owner = {
				NOT = { has_technology = tech_mine_zro }
			}
		}
		on_select = {
			custom_tooltip = breach_shroud_commune_resources_tooltip
			if = {
				limit = {
					owner = { NOT = { has_country_flag = sr_zro_found } }
				}
				custom_tooltip = breach_shroud_commune_resources_unknown_tt
			}
			else = {
				custom_tooltip = breach_shroud_commune_resources_discovered_tt
			}
		}
		modifier = {
			country_unity_produces_mult = -0.50
		}
		ai_weight = {
			base = 10 # Getting the tech is top priority (unless you have lots of astral threads to spend)
		}
	}
	approach = {
		name = approach_situation_breach_shroud_distribute_zro
		icon = GFX_situation_approach_zro
		icon_background = GFX_situation_approach_bg_yellow
		potential = {
			owner = { has_technology = tech_mine_zro }
		}
		allow = {
			owner = {
				has_resource = {
					type = sr_zro
					amount >= 1
				}
			}
		}
		on_select = {
			set_situation_flag = chaotic_approach
			custom_tooltip = approach_situation_chaotic_tooltip
			custom_tooltip = breach_shroud_distribute_zro_tooltip
		}
		resources = {
			category = situations
			upkeep = {
				trigger = {
					NOR = {
						AND = {
							current_stage = stage_2
							owner = {
								has_active_psi_corps = no
							}
						}
						AND = {
							current_stage = stage_3
							owner = {
								NOT = {
									has_tradition = tr_psionics_shroud_great_awakening
								}
							}
						}
					}
				}
				sr_zro = 1
			}
		}
		modifier = {
			country_unity_produces_mult = 0.25
		}
		ai_weight = {
			base = 0
			modifier = {
				add = 1
				owner = { has_ethic = ethic_materialist }
			}
			modifier = {
				add = 2
				owner = { has_ethic = ethic_fanatic_materialist }
			}
		}
	}
	approach = {
		name = approach_situation_breach_shroud_commune_planes
		icon = GFX_situation_approach_astral
		icon_background = GFX_situation_approach_bg_yellow
		potential = {
			has_astral_planes_dlc = yes
			owner = { NOT = { has_technology = tech_astral_harvesting } }
		}
		on_select = {
			custom_tooltip = breach_shroud_commune_planes_tooltip
			if = {
				limit = {
					owner = { NOT = { has_country_flag = astral_threads_found } }
				}
				custom_tooltip = breach_shroud_commune_planes_unknown_tt
			}
			else = {
				custom_tooltip = breach_shroud_commune_planes_discovered_tt
			}
		}
		modifier = {
			country_unity_produces_mult = -0.50
		}
		ai_weight = {
			base = 0 # AIs aren't interested in getting the astral tech from this situation
		}
	}
	approach = {
		name = approach_situation_breach_shroud_unravel_thread
		icon = GFX_situation_approach_threads
		icon_background = GFX_situation_approach_bg_yellow
		potential = {
			has_astral_planes_dlc = yes
			owner = { has_technology = tech_astral_harvesting }
		}
		allow = {
			owner = {
				has_resource = {
					type = astral_threads
					amount >= 10
				}
			}
		}
		on_select = {
			set_situation_flag = chaotic_approach
			custom_tooltip = approach_situation_chaotic_tooltip
			custom_tooltip = breach_shroud_unravel_thread_tooltip
		}
		resources = {
			category = situations
			upkeep = {
				trigger = {
					NOR = {
						AND = {
							current_stage = stage_2
							owner = {
								has_active_psi_corps = no
							}
						}
						AND = {
							current_stage = stage_3
							owner = {
								NOT = {
									has_tradition = tr_psionics_shroud_great_awakening
								}
							}
						}
					}
				}
				astral_threads = 10
			}
		}
		modifier = {
			country_unity_produces_mult = 0.1
		}
		ai_weight = {
			base = 0
			modifier = {
				add = 5 # Higher priority than ethic choices, but zro tech is still higher prio
				owner = { has_resource = { type = astral_threads amount >= 10 } }
			}
			modifier = {
				factor = 10
				owner = { has_resource = { type = astral_threads amount > 100 } }
			}
		}
	}

	monthly_progress = {
		modifier = {
			desc = BASE
			set = 5
		}
		modifier = {
			desc = string_current_approach
			factor = 0.75
			current_situation_approach = approach_situation_breach_shroud_nothing
		}
		modifier = {
			desc = string_current_approach
			factor = 1.25
			current_situation_approach = approach_situation_breach_shroud_distribute_zro
		}
		modifier = {
			desc = string_current_approach
			factor = 1.1
			current_situation_approach = approach_situation_breach_shroud_unravel_thread
		}
		modifier = {
			mult = 1.05
			desc = "tr_psionics_shroud_telekinesis"
			owner = { has_tradition = tr_psionics_shroud_telekinesis }
		}
		modifier = {
			mult = 1.05
			desc = "tr_psionics_shroud_clairvoyance"
			owner = { has_tradition = tr_psionics_shroud_clairvoyance }
		}
		modifier = {
			mult = 1.05
			desc = "tr_psionics_shroud_psychometry"
			owner = { has_tradition = tr_psionics_shroud_psychometry }
		}
		modifier = {
			desc = situation_breach_shroud_progress_speed_desc
			factor = value:breach_the_shroud_situation_progress_speed_factor
			owner = {
				check_modifier_value = {
					modifier = breach_the_shroud_situation_progress_speed_mult
					value != 0
				}
			}
		}
		modifier = {
			mult = 0
			desc = situation_breach_shroud_psi_corps_needed_desc
			AND = {
				current_stage = stage_2
				owner = {
					has_active_psi_corps = no
				}
			}
		}
		modifier = {
			mult = 0
			desc = situation_breach_shroud_great_awakening_needed_desc
			AND = {
				current_stage = stage_3
				owner = {
					NOT = {
						has_tradition = tr_psionics_shroud_great_awakening
					}
				}
			}
		}
		modifier = {
			desc = situation_breach_shroud_shroud.2520.slowness
			factor = 0.75
			has_situation_flag = shroud.2520.slowness
		}
	}
	triggered_blocked_desc = {
		trigger = {
			current_stage = stage_2
			owner = {
				has_active_psi_corps = no
			}
		}
		text = "situation_breach_shroud_psi_corps_needed_desc"
	}
	triggered_blocked_desc = {
		trigger = {
			current_stage = stage_3
			owner = {
				NOT = {
					has_tradition = tr_psionics_shroud_great_awakening
				}
			}
		}
		text = "situation_breach_shroud_great_awakening_needed_desc"
	}

	on_monthly = {
		events = {
			# Approaches
			shroud.2160	# For tech_mine_zro progression
			shroud.2165	# For tech_astral_harvesting progression
			shroud.2170
			shroud.2175
			# Random events
			shroud.2200
		}
	}
}

