	approach = {
		name = situation_experimental_testing_society
		icon = GFX_situation_approach_society
		icon_background = GFX_situation_approach_bg_yellow
		on_select = {
			custom_tooltip = situation_experimental_testing_society_outcome_tt
			set_situation_flag = situation_experimental_testing_society
		}
		allow = {
			custom_tooltip = situation_experimental_testing_locked_tt
			hidden_trigger = {
				NOR = {
					has_situation_flag = situation_experimental_testing_physics
					has_situation_flag = situation_experimental_testing_engineering
				}
			}
		}
		ai_weight = {
			base = 1
		}
	}
	approach = {
		name = situation_experimental_testing_engineering
		icon = GFX_situation_approach_engineering
		icon_background = GFX_situation_approach_bg_yellow
		on_select = {
			custom_tooltip = situation_experimental_testing_engineering_outcome_tt
			set_situation_flag = situation_experimental_testing_engineering
		}
		allow = {
			custom_tooltip = situation_experimental_testing_locked_tt
			hidden_trigger = {
				NOR = {
					has_situation_flag = situation_experimental_testing_physics
					has_situation_flag = situation_experimental_testing_society
				}
			}
		}
		ai_weight = {
			base = 1
		}
	}

	triggered_modifier = {
		potential = {
			OR = {
				current_situation_approach = situation_experimental_testing_physics
				current_situation_approach = situation_experimental_testing_society
				current_situation_approach = situation_experimental_testing_engineering
			}
		}
		experimental_testing_test_subjects_death = @experimental_testing_test_subject_death_mult
	}
	monthly_progress = {
		base = 1
		modifier = {
			desc = string_current_approach
			current_situation_approach = situation_experimental_testing_hold
			factor = 0
		}
		modifier = {
			desc = situation_experimental_testing_testing_lockdown_desc
			owner = { has_modifier = testing_lockdown }
			factor = 0
		}
		modifier = {
			desc = situation_experimental_testing_no_test_subject_desc
			owner = {
				check_variable_arithmetic = {
					which = value:count_test_subjects
					value <= 0
				}
			}
			factor = 0
		}
		modifier = {
			desc = situation_experimental_testing_monthly_change_mult_tooltip
			check_variable_arithmetic = {
				which = owner.value:count_test_subjects
				value > 0
			}
			factor = owner.value:experimental_testing_speed_mult
		}
		modifier = {
			desc = situation_experimental_testing_example_set_mult_tooltip
			owner = { has_modifier = example_set }
			factor = 1.1
		}
	}

	abort_trigger = {
		OR = {
			NOT = { exists = target.owner }
			target.owner = {
				OR = {
					NOT = { is_same_value = root.owner }
					is_twisted_experimenters_empire = no
				}
			}
		}
	}

	on_progress_complete = {
		custom_tooltip = situation_experimental_testing_outcome
		hidden_effect = {
			situation_event = { id = shroud.1010 }
		}
	}
}

